  //    assert((total < 0) || (available <= total));
  //    assert(pos < available);
  //    assert((available - pos) >= 1);  //assume here max u-int len is 8
  //#endif

  len = 1;

  unsigned char b;

  status = pReader->Read(pos, 1, &b);

