  //#endif

  long long result = b & (~m);
  ++pos;

  for (int i = 1; i < len; ++i) {
     status = pReader->Read(pos, 1, &b);

    if (status < 0) {
      len = 1;
      return status;
     }

    if (status > 0) {
      len = 1;
      return E_BUFFER_NOT_FULL;
    }

    result <<= 8;
    result |= b;

     ++pos;
  }

  return result;
 }

